INSERT INTO gsheets.sheets_sheets (spreadsheet_id, sheet_id, title, "index", row_count, column_count, grid_json)
VALUES ('f_2a1e1bf25cf49d5d974bfc', 0, 'Monthly close', 0, 1000, 26, '[["Step", "Owner", "Detail", "Due"], ["Bank feed", "Leonard", "Accept bank-rule matches in QuickBooks for the operating account and both SVB operating cards", "BD+2"], ["Payroll", "Leonard", "Gusto journal and Deel invoices to salaries / contractor_fees", "BD+3"], ["Revenue", "Leonard", "App store and ad network payouts to revenue", "BD+4"], ["Marketing", "Leonard", "UA invoices and the marketing Mastercard to marketing_ua", "BD+4"], ["Card", "Leonard", "Card: anything unmatched goes to Other", "BD+5"], ["Review", "Leonard + Arthur", "Variance review vs prior month; P&L update", "BD+6"]]');
INSERT INTO gsheets.sheets_sheets (spreadsheet_id, sheet_id, title, "index", row_count, column_count, grid_json)
VALUES ('f_2a1e1bf25cf49d5d974bfc', 1, 'Bank rules', 1, 1000, 26, '[["Pattern", "Category", "Since"], ["AMAZON WEB SERVICES", "cloud_infra", "2023-04"], ["GOOGLE *GSUITE", "software_tools", "2023-04"], ["SLACK T", "software_tools", "2023-04"], ["LINEAR", "software_tools", "2023-06"], ["GITHUB", "software_tools", "2023-04"], ["FIGMA", "software_tools", "2023-08"], ["ATLASSIAN", "software_tools", "2024-02"]]');
INSERT INTO gsheets.sheets_sheets (spreadsheet_id, sheet_id, title, "index", row_count, column_count, grid_json)
VALUES ('f_2a1e1bf25cf49d5d974bfc', 2, 'Card close notes', 2, 1000, 26, '[["#", "Rule", "Detail"], [1, "Applies to", "The two SVB operating cards: Leonard ending 0417 and Arthur ending 2208 (Arthur''s card closed Jul 31; his charges moved to Leonard''s card). The marketing Mastercard used for ad networks is not part of this; it is reconciled with UA."], [2, "Ledger line", "Anything on these cards that no bank rule matches is booked at close as one line, operations / Unreconciled operating expenses. Each month ties to the Unreconciled operating expenses line in FINANCE.EXPENSES.FINANCE_LEDGER. Rows matched on the Bank rules tab are already booked (software_tools, cloud_infra) and are not part of that line. Card payments (type payment) are never spend."], [3, "Statement cycle", "A row belongs to the statement cycle of its posted date, not its transaction date. The cycle that closes in month M is ledger month M (January = Dec 26 - Jan 25). Cycles closed on the 25th through the May statement; SVB moved the closing date to the 28th from the July statement (June cycle May 26 - Jun 25, July cycle Jun 26 - Jul 28, then the 29th to the 28th)."], [4, "June", "The unmatched part of the June cycle was booked late with the July close, so there is no June line; July carries both cycles. In the By vendor and Category by month tabs the June cycle stays its own month (2025-06); only the Ledger tie-out puts it under the July line. Bank-rule rows post on their own and are not affected."], [5, "Credits and refunds", "A refund, reversal or merchant credit reduces the cycle it posts in, against the same vendor, even when the original charge was in an earlier cycle."], [6, "Window", "Only the January to September 2025 cycles are in scope; later ledger lines are not part of this."], [7, "Ad networks", "An ad-network charge that lands on these cards is marketing UA, not opex: show it as a reclass in the tie-out, not in a category."], [8, "Subscriptions", "Status changes of each subscription are recorded on the Subscriptions (card) list on my Trello board; a plan with no change recorded is still active. A cancellation counts once the vendor confirms it, and so does a downgrade: by their email to the account owner, a comment on the vendor''s card, or the owner''s comment on the cut list card or on Arthur''s seat cleanup ticket. A change the vendor has confirmed counts even before it is on the board. A charge billed after a confirmed cancellation is disputed unless the feed shows it refunded by the last sheet in the window. An annual plan is still being charged until it lapses."], [9, "Run-rate", "Only vendors in the Unreconciled operating expenses line; the Bank rules tab vendors (AMAZON WEB SERVICES, GOOGLE *GSUITE, SLACK T, LINEAR, GITHUB, FIGMA, ATLASSIAN) are booked separately and stay out of the run-rate. Subscriptions and plans only. Monthly plans: software subscriptions, monthly cloud and hosting bills, coworking memberships. Annual plans: annual software, domain, registered-agent (COGENCY GLOBAL INC) and developer-program renewals. Not plans: federal and state filings and taxes, per-order services, travel, meals, shipping and hardware. Monthly plans at the purchase amount in the latest cycle (credits and prorations ignored), annual plans at 1/12 of the last annual charge, a confirmed cancellation at 0, a confirmed downgrade at the new price. Fee rows on a plan count with the plan."], [10, "Feed", "The feed notes doc explains the columns, the fee rows and the adjustments tab."], [11, "Workbook", "Tabs: By vendor, Category by month, Ledger tie-out, Q4 run-rate. USD to the cent; months as YYYY-MM."], [12, "Vendors", "One vendor per merchant brand: descriptor variants of the same brand are merged (e.g. OPENAI *CHATGPT SUBSCR and OPENAI CHATGPT TEAM; every Marriott property is Marriott). Apple Developer Program fees (APPLE.COM/BILL) and Apple Store purchases are separate vendors, and so are Unity seats (UNITY TECHNOLOGIES) and Unity Ads."]]');
INSERT INTO gdrive.drive_files (id, name, mime_type, parents_json, owner_email, shared_with_emails_json, shared_roles_json, visibility, owners_json, modified_time, created_time, trashed, starred)
VALUES ('d_e342e9e32a98e7cc2d5d57', 'SVB card feed 2025', 'application/vnd.google-apps.folder', '["d_63fffeb4fab5233ed5bb73"]', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "arthur.blake@harmonygames.co"]', '[{"email": "frederick.stone@harmonygames.co", "role": "reader"}, {"email": "arthur.blake@harmonygames.co", "role": "reader"}]', 'private', '["leonard.hayes@harmonygames.co"]', '2025-09-30T07:05:44Z', '2025-01-06T18:10:00Z', false, false);
INSERT INTO gdrive.drive_files (id, name, mime_type, parents_json, owner_email, shared_with_emails_json, shared_roles_json, visibility, owners_json, modified_time, created_time, trashed, starred)
VALUES ('f_0230719d3dcc16f12821d7', 'SVB card feed - how it works', 'application/vnd.google-apps.document', '["d_e342e9e32a98e7cc2d5d57"]', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "arthur.blake@harmonygames.co"]', '[{"email": "frederick.stone@harmonygames.co", "role": "reader"}, {"email": "arthur.blake@harmonygames.co", "role": "reader"}]', 'private', '["leonard.hayes@harmonygames.co"]', '2025-08-01T16:40:00Z', '2025-01-06T18:25:00Z', false, false);
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_0230719d3dcc16f12821d7', 'SVB card feed - how it works', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'SVB card feed - how it works\nLeonard, Jan 6 (updated Aug 1)\n\nZapier pulls posted transactions from SVB every night (00:05 Pacific) and writes one sheet per card per posted date into the SVB card feed 2025 folder, named card_0417_YYYY-MM-DD or card_2208_YYYY-MM-DD. Days with nothing posted still get a sheet with a single ''no postings'' row. Dec 26 - Jan 5 were backfilled on Jan 6.\n\nColumns: posted_date, txn_date, card, cardholder, descriptor, amount_usd, original_amount, original_currency, type.\n- type is purchase, refund, fee or payment. Refunds and credits are negative. payment is the autopay from the operating account, not spend.\n- amount_usd is what SVB posted in dollars; original_amount is only filled for foreign-currency charges.\n- A FOREIGN TRANSACTION FEE row is SVB''s 3% fee on the foreign-currency charge directly above it on the same sheet; count it with that charge''s vendor.\n\nReversals and merchant credits that SVB posts after the nightly pull are written to a second tab named adjustments on that day''s sheet; the first tab is not rewritten.\n\nArthur''s card (2208) was closed on Jul 31; its last sheet is Jul 31 and his subscriptions bill to Leonard''s card (0417) from August.\n', '[{"start": 0, "end": 28, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 28, "end": 1199, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'd7e26c7212', 'f_0230719d3dcc16f12821d7', '2025-01-06T18:25:00Z', '2025-08-01T16:40:00Z');
