INSERT INTO gmail.gmail_threads (id, user_email, snippet, history_id)
VALUES ('leonard.hayes@harmonygames.co/1840271709962717824', 'leonard.hayes@harmonygames.co', 'Hi Leonard, Thanks for getting Q2 in. One request for Q3: a large part of your 2025 opex is reported as Other, and our LPs ask us for a cons', NULL);
INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('leonard.hayes@harmonygames.co/<SN6PR08MBFC51FAAD@SN6PR08MB4655.namprd08.prod.outlook.com>', 'leonard.hayes@harmonygames.co/1840271709962717824', 'leonard.hayes@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Hi Leonard, Thanks for getting Q2 in. One request for Q3: a large part of your 2025 opex is reported as Other, and our LPs ask us for a cons', 1755019865000, '2025-08-12T17:31:05Z', 2241, 'Q2 metrics - opex categories', 'PERSON_2847_EMAIL', 'PERSON_2847_NAME', '["Leonard Hayes <leonard.hayes@harmonygames.co>"]', '[]', '[]', '[]', E'Hi Leonard,\r\n\r\nThanks for getting Q2 in. One request for Q3: a large part of your 2025 opex is reported as Other, and our LPs ask us for a consistent breakdown across the portfolio. From the Q3 submission please report non-payroll opex in our 2025 categories:\r\n\r\nSoftware & subscriptions: all SaaS and app subscriptions, whichever team uses them, including AI tools, design and stock libraries, market-intelligence tools, e-signature, e-mail and scheduling tools, automation tools and app store developer program fees.\r\nHosting & infrastructure: cloud, backend-as-a-service, domains, and website builders and hosting.\r\nResearch & user testing: paid playtests, surveys and research panels.\r\nMarketing (non-UA): creative production and freelancers for marketing assets (store screenshots, trailers).\r\nTravel & events: flights, hotels, ground transport and conference passes.\r\nHardware & equipment: devices, test hardware and accessories, including retail purchases of them.\r\nProfessional & admin: legal and accounting, payroll, HR, equity and accounting platforms, registered agent, federal and state filings and fees.\r\nOther G&A: bank fees not tied to a purchase, shipping, coworking and office, and team meals.\r\n\r\nPaid user acquisition is reported separately and should not be in opex. Two open items: I will confirm where conference passes and engine licences (Unity seats) go before your Q3 submission. These replace the 2024 list.\r\n\r\nBest,\r\nPERSON_2847_NAME', NULL, '[{"name": "Message-ID", "value": "<SN6PR08MBFC51FAAD@SN6PR08MB4655.namprd08.prod.outlook.com>"}, {"name": "Date", "value": "Tue, 12 Aug 2025 17:31:05 +0000"}, {"name": "Subject", "value": "Q2 metrics - opex categories"}, {"name": "From", "value": "PERSON_2847_NAME <PERSON_2847_EMAIL>"}, {"name": "To", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('leonard.hayes@harmonygames.co/<SN6PR08MBFC51FB12@SN6PR08MB4655.namprd08.prod.outlook.com>', 'leonard.hayes@harmonygames.co/1840271709962717824', 'leonard.hayes@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Hi Leonard, On the two open items from my August note: conference passes (GDC and the like) go under Marketing (non-UA) for 2025, not', 1759244300000, '2025-09-30T14:58:20Z', 1180, 'Re: Q2 metrics - opex categories', 'PERSON_2847_EMAIL', 'PERSON_2847_NAME', '["Leonard Hayes <leonard.hayes@harmonygames.co>"]', '[]', '[]', '[]', E'Hi Leonard,\r\n\r\nOn the two open items from my August note: conference passes (GDC and the like) go under Marketing (non-UA) for 2025, not Travel & events; flights, hotels and ground transport for the same trips stay in Travel & events. Engine licences (Unity seats) go under Hosting & infrastructure with the rest of the game stack, not Software & subscriptions.\r\n\r\nBest,\r\nPERSON_2847_NAME', NULL, '[{"name": "Message-ID", "value": "<SN6PR08MBFC51FB12@SN6PR08MB4655.namprd08.prod.outlook.com>"}, {"name": "Date", "value": "Tue, 30 Sep 2025 14:58:20 +0000"}, {"name": "Subject", "value": "Re: Q2 metrics - opex categories"}, {"name": "From", "value": "PERSON_2847_NAME <PERSON_2847_EMAIL>"}, {"name": "To", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}]', '<SN6PR08MBFC51FAAD@SN6PR08MB4655.namprd08.prod.outlook.com>', NULL, NULL, '[]');
