VALUES ('04a47c75938e764349dbad55bb83239a', '1758910840.227619', 'C07C2866011', 'message', 'EMPLOYEE_0038_SLACK_ID', 'change on the cut list: keep Sensor Tower through the bridge, investors keep asking for market data. cancel AppMagic instead (Fred). rest of the list stands', '56b67a8161dda95587f9c5f4fc18abbc', '1758649512.418329', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-26T18:20:40.227619Z', '{}');
