VALUES ('5fad9bbec1eeea1c38d78b4c1cdfe1e1', '1758824317.660149', 'C07C2866011', 'message', 'EMPLOYEE_0016_SLACK_ID', 'for the griffin thing can we just put all the card stuff under software? nobody there reads the breakdown', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-25T18:18:37.660149Z', '{}');
