VALUES ('5db26ce6ec5c4a60830f5bf2cf3ef1d6', '1759248331.512089', 'D05S58U4SAK', 'message', 'EMPLOYEE_0038_SLACK_ID', 'for the card breakdown reply, add Robert, he needs the Q3 numbers for the investor update. Arthur stays on. I''m putting a review on Friday', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T16:05:31.512089Z', '{}');
