VALUES ('eb62705cd9e5048928e9261eb3622f39', '1759248472.204417', 'D05S58U4SAK', 'message', 'EMPLOYEE_0038_SLACK_ID', 'and Griffin answered his two open items on the categories: conference passes go under Marketing (non-UA), not Travel & events, and Unity seats go under Hosting & infrastructure, not Software & subscriptions. Use those for the Q3 numbers', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T16:07:52.204417Z', '{}');
