-- ===================== CONFLUENCE =====================
INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at)
VALUES ('page_ops_card_close', 'space_OPS', 'page_ops_home', 'Month-end close - card', '<p>How we close the company card each month (Leonard).</p><ul><li>Statement closes on the 25th.</li><li>Anything not matched by a bank rule goes to Other.</li><li>Refunds: net against the month of the original charge.</li><li>FX fees: book to bank fees (Other).</li><li>Ad network charges: marketing_ua.</li></ul>', 'storage', 'current', 2, 'user_EMPLOYEE_0038', '2024-02-20T19:05:00Z', '2024-06-10T18:30:00Z');
INSERT INTO confluence.confluence_page_versions (id, page_id, number, title, body, author_id, message, created_at)
VALUES ('ver_d2a08543e21b921c0b6059c6b348a761', 'page_ops_card_close', 1, 'Month-end close - card', '<p>How we close the company card each month (Leonard).</p><ul><li>Statement closes on the 15th.</li><li>Anything not matched by a bank rule goes to Other.</li><li>Refunds: net against the month of the original charge.</li></ul>', 'user_EMPLOYEE_0038', NULL, '2024-02-20T19:05:00Z');
INSERT INTO confluence.confluence_page_versions (id, page_id, number, title, body, author_id, message, created_at)
VALUES ('ver_068bf64a92e27b4d7fc42c369ea1e825', 'page_ops_card_close', 2, 'Month-end close - card', '<p>How we close the company card each month (Leonard).</p><ul><li>Statement closes on the 25th.</li><li>Anything not matched by a bank rule goes to Other.</li><li>Refunds: net against the month of the original charge.</li><li>FX fees: book to bank fees (Other).</li><li>Ad network charges: marketing_ua.</li></ul>', 'user_EMPLOYEE_0038', 'SVB moved the statement date', '2024-06-10T18:30:00Z');
INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at)
VALUES ('page_ops_standard_metrics', 'space_OPS', 'page_ops_home', 'Standard Metrics - opex categories (Griffin)', '<p>Griffin''s opex buckets for the quarterly upload: Software (all tools incl. Gusto/payroll and Carta), Hosting, Marketing (incl. Sensor Tower type data tools, playtests, stock assets), Travel, Equipment, Legal &amp; accounting, Other (anything experimental, e.g. AI tools).</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0038', '2024-05-14T17:50:00Z', '2024-05-14T17:50:00Z');
INSERT INTO confluence.confluence_page_versions (id, page_id, number, title, body, author_id, message, created_at)
VALUES ('ver_c821a213ba2e09485ba8b9477d8c1d55', 'page_ops_standard_metrics', 1, 'Standard Metrics - opex categories (Griffin)', '<p>Griffin''s opex buckets for the quarterly upload: Software (all tools incl. Gusto/payroll and Carta), Hosting, Marketing (incl. Sensor Tower type data tools, playtests, stock assets), Travel, Equipment, Legal &amp; accounting, Other (anything experimental, e.g. AI tools).</p>', 'user_EMPLOYEE_0038', NULL, '2024-05-14T17:50:00Z');
