VALUES ('ENG-2370', NULL, 'team_ENG', NULL, 'usr_cc3e90160f490686', 'usr_cc3e90160f490686', 'In Progress', NULL, 'ENG-2370', 2370, 'Seat cleanup (Unity, 1Password) + Edgegap plan', 'My card (2208) closed Jul 31. Unity Pro, 1Password, Edgegap and Google Cloud bill to Leonard''s card since August. Drop seats nobody uses and look at a cheaper Edgegap plan.', 3, NULL, NULL, '2025-09-03T16:24:00Z', NULL, NULL, NULL, NULL, '[]', '[]', '[]', '[]', false, '2025-09-03T16:20:00Z', '2025-09-24T19:05:00Z');
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('cmt_6a3ed6d55230ef92c211', 'ENG-2370', 'usr_cc3e90160f490686', NULL, 'for the record: Fred''s Unity seat came off Jul 18, so we were on 5 seats from the Aug bill. On Aug 8 I switched Unity Pro to the annual prepay for those 5 seats, charged to Leonard''s card - cheaper than monthly', false, '2025-09-03T16:24:00Z', '2025-09-03T16:24:00Z', 1);
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('cmt_a37dfbf75e0965ec75d6', 'ENG-2370', 'usr_cc3e90160f490686', NULL, 'Asked Edgegap for the smaller plan, $420.00/month. They still have to confirm it and which invoice it would start from - I''ll post here once they do', false, '2025-09-24T19:05:00Z', '2025-09-24T19:05:00Z', 2);
